int main(void){UmiDataServer *server=NULL;UmiStudioServices *services;UmiStudioDatabaseExplorerCentre *c=NULL;char m[512];extern UmiStudioServices *umi_test_services_create(UmiDataServer *server);extern void umi_test_services_destroy(UmiStudioServices *services);assert(umi_studio_database_commands_count()==UMI_STUDIO_DATABASE_COMMAND_COUNT);assert(umi_data_server_create_memory(&server)==UMI_STATUS_OK);services=umi_test_services_create(server);assert(umi_studio_database_explorer_create(services,&c)==UMI_STATUS_OK);assert(umi_studio_database_command_execute(c,"database.write-mode.enable",NULL,m,sizeof(m))==UMI_STATUS_OK);assert(umi_studio_database_command_execute(c,"database.transaction.begin",NULL,m,sizeof(m))==UMI_STATUS_OK);assert(umi_studio_database_command_execute(c,"database.query.execute","SET project umicom",m,sizeof(m))==UMI_STATUS_OK);assert(strstr(m,"OK")!=NULL);assert(umi_studio_database_command_execute(c,"database.transaction.commit",NULL,m,sizeof(m))==UMI_STATUS_OK);umi_studio_database_explorer_destroy(c);umi_test_services_destroy(services);umi_data_server_destroy(server);return 0;}
